    func fetchRoomHistory(roomJid: String, maxMessages: UInt32, beforeId: String?) async  -> WaddleMamPage
    
    func joinRoom(roomJid: String, nick: String) async 
    
    func leaveRoom(roomJid: String, nick: String) async 
    
